            inParentheses = true;
            if (currentSegment.length() > maxCount) maxCount = currentSegment.length();
            currentSegment.clear();
        } else if (ch == ')') {
            inParentheses = false;
            if (!currentSegment.empty()) {
                segments.push_back(currentSegment);
                currentSegment.clear();
            }
        } else if (std::isalpha(ch)) {
            currentSegment += ch;
        } else if (ch == '_') {
            if (inParentheses) {
                if (!currentSegment.empty()) {
                    segments.push_back(currentSegment);
                    currentSegment.clear();
                }
            } else {
                if (currentSegment.length() > maxCount) maxCount = currentSegment.length();
                currentSegment.clear();
            }
        }
    }
    if (currentSegment.length() > maxCount) maxCount = currentSegment.length();

    std::cout << maxCount << " " << segments.size() << std::endl;

    return 0;
